===OwnerRegion===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Derives an owner's region code — the {@code <REGION>} segment of the
 * {@code <REGION>-<HASH8>} {@code customerCode} and the source of the owner's locality.
 *
 * <p>The postcode is preferred: a four-digit postcode is mapped by inclusive range
 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). When the postcode is absent or in no
 * known range, falls back to the fixed city-to-region table (Sydney-&gt;NSW,
 * Melbourne-&gt;VIC, Brisbane-&gt;QLD), otherwise {@code "UNKNOWN"}.
 */
public final class OwnerRegion {

    private OwnerRegion() {
    }

    /** Region derived from the postcode, falling back to the city, else {@code "UNKNOWN"}. */
    public static String fromPostcodeOrCity(String postcode, String city) {
        if (postcode != null && postcode.matches("[0-9]{4}")) {
            int value = Integer.parseInt(postcode);
            if (value >= 2000 && value <= 2099) return "NSW";
            if (value >= 3000 && value <= 3099) return "VIC";
            if (value >= 4000 && value <= 4099) return "QLD";
        }
        if ("Sydney".equals(city)) return "NSW";
        if ("Melbourne".equals(city)) return "VIC";
        if ("Brisbane".equals(city)) return "QLD";
        return "UNKNOWN";
    }
}
===AssignMembershipLevel===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Scores the owner's {@code membershipPoints} at creation, then maps them to a numeric
 * {@code membershipLevel} (1 to 4).
 *
 * <p>Points start at {@code 0}; add {@code 2} when an email is present; add {@code 1} when
 * {@code namesakeCount} is {@code 0}; add {@code 2} for a household of {@code 3} or more; add
 * {@code 3} when at least one fiscal year has elapsed since registration.
 *
 * <p>Points map to level as: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or
 * more points.
 *
 * <p>Level 4 requires 6 points, and the only route to 6 is the tenure factor (+3). A newly
 * created owner has zero tenure (it registers in the current fiscal year), so the tenure factor
 * never applies at creation and a new owner never exceeds level 3.
 *
 * <p>Runs after {@link AssignNamesakeCount} and {@link AssignHouseholdSize} (so those counts are
 * set) and before {@link SaveOwner}, so both fields are persisted and available to the create
 * audit line.
 */
public class AssignMembershipLevel {

    /** Tenure threshold, in elapsed fiscal years, at or above which the tenure factor is awarded. */
    private static final int TENURE_FISCAL_YEARS_THRESHOLD = 1;

    public void service(@Val Owner owner) {
        int points = 0;
        String email = owner.getEmail();
        if (email != null && !email.isBlank()) {
            points += 2;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            points += 1;
        }
        Integer householdSize = owner.getHouseholdSize();
        if (householdSize != null && householdSize >= 3) {
            points += 2;
        }
        if (tenureFiscalYears(owner) >= TENURE_FISCAL_YEARS_THRESHOLD) {
            points += 3;
        }
        owner.setMembershipPoints(points);
        owner.setMembershipLevel(levelForPoints(points));
    }

    /** Maps points to level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
    private static int levelForPoints(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }

    /**
     * Whole fiscal years elapsed since registration; zero (or negative) for an owner registered in
     * the current fiscal year.
     */
    private static int tenureFiscalYears(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return 0;
        }
        return FiscalYear.elapsed(registrationDate, LocalDate.now());
    }
}
===CapMembershipLevel===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Caps the new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
 * {@code membershipLevel} among the existing members of its household (owners sharing the same
 * {@link AssignHouseholdId#deriveHouseholdId householdId}). A joining member cannot leapfrog the
 * household: the level becomes {@code min(assignedLevel, maxExistingMemberLevel + 1)}.
 *
 * <p>The cap targets a <em>silent</em> joiner — one admitted into the household by
 * {@link RequireUniqueOwnerHousehold} on the strength of its own distinct email rather than by
 * declaring {@code sharesHousehold}. A member the caller explicitly declares with
 * {@code sharesHousehold} true is trusted and keeps its assigned level, so the tenure/points model
 * (e.g. the household-size bonus that lifts a declared third member to level 3) is preserved.
 *
 * <p>When there is no existing household member — the owner has no {@code householdId}, or is the
 * only member so far — no cap applies and the assigned level is left untouched.
 *
 * <p>Runs after {@link AssignMembershipLevel} (which assigns the uncapped level) and before
 * {@link SaveOwner}, so the capped value is what is persisted and returned. The new owner is not
 * yet saved, so the repository scan sees only the pre-existing members.
 */
public class CapMembershipLevel {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
            OwnerRepository ownerRepository) {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member is trusted and not capped
        }
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return;
        }
        Integer level = owner.getMembershipLevel();
        if (level == null) {
            return;
        }
        Integer maxExisting = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue; // never count the new owner against itself
            }
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner is not a household member
            }
            if (!householdId.equals(existing.getHouseholdId())) {
                continue;
            }
            Integer existingLevel = existing.getMembershipLevel();
            if (existingLevel != null && (maxExisting == null || existingLevel > maxExisting)) {
                maxExisting = existingLevel;
            }
        }
        if (maxExisting == null) {
            return; // no existing household member -> no cap applies
        }
        int ceiling = maxExisting + 1;
        if (level > ceiling) {
            owner.setMembershipLevel(ceiling);
        }
    }
}

